/**
 * Whaleal Cart 安装页 — Free 试用优先，双入口（OAuth + App Store）
 * 多语言：文案来自 i18n/dictionaries/install.js，产品名与域名等常量保持品牌原样。
 * @author 恒哥
 */
import React, { useState } from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import FreeInstallCta from '../components/FreeInstallCta';
import {
  PRODUCT_NAME,
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_APP_URL,
  SHOPIFY_API_URL,
  buildOAuthInstallUrl,
  normalizeShopDomain,
} from '../constants/brand';
import { usePageI18n } from '../i18n';
import installCopy from '../i18n/dictionaries/install';
import { buildTrackingUrl, getSourceParams, trackEvent } from '../utils/analytics';
import './page.css';
import '../components/FreeInstallCta/free-install-cta.css';

/** 把文案里的 {product} / {store} / {host} 等占位符替换成真实值 */
function fill(str, vars) {
  return Object.keys(vars).reduce((acc, k) => acc.replace(`{${k}}`, vars[k]), str);
}

export default function InstallPage({ pageContext }) {
  const { locale, localePath, t } = usePageI18n(pageContext);
  const c = installCopy[locale] || installCopy.en;
  const vars = {
    product: PRODUCT_NAME,
    productFull: PRODUCT_NAME_FULL,
    store: SHOPIFY_APP_STORE_LABEL,
    host: new URL(SHOPIFY_API_URL).host,
    appHost: new URL(SHOPIFY_APP_URL).host,
  };

  const [shopInput, setShopInput] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const startOAuth = (rawShop) => {
    const shop = normalizeShopDomain(rawShop);
    if (!shop) {
      setError(t.install.invalidDomain);
      trackEvent('install_error', { error_type: 'invalid_domain', locale });
      return false;
    }
    const url = buildOAuthInstallUrl(shop);
    if (!url) {
      setError(t.install.urlError);
      trackEvent('install_error', { error_type: 'no_url', locale });
      return false;
    }
    setSubmitting(true);
    // 🔴 归因关键一步：把来源参数（utm_* / gclid / ref）拼进 OAuth URL，
    //    让它穿过 Shopify 域落到后端落库 —— 否则 GA4 只知道「有人点了」，
    //    永远回答不了「哪个渠道真的装了」。
    //    🔴 只传来源标记，绝不把 store 域名本身回传给分析脚本。
    trackEvent('install_start', { locale, has_source: Boolean(getSourceParams()) });
    window.location.assign(buildTrackingUrl(url));
    return true;
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    startOAuth(shopInput);
  };

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={fill(c.metaTitle, vars)}
        description={fill(c.metaDesc, vars)}
        pathname="/install"
        hrefLang={locale}
      />
      <div className="page-container about-page">
        <div className="page-header about-header">
          <h1>{fill(c.pageTitle, vars)}</h1>
          <p>{fill(c.pageLead, vars)}</p>
        </div>

        <div className="about-content">
          <FreeInstallCta
            variant="inline"
            title={c.freeNoteTitle}
            className="install-free-note"
            hideActions
          />

          <section className="about-section" style={{ marginTop: '2rem' }}>
            <h2>{c.opt1Title}</h2>
            <p>{fill(c.opt1Body, vars)}</p>

            <form
              id="install-form"
              onSubmit={handleSubmit}
              className="install-form"
              action="#"
              method="get"
            >
              <label htmlFor="shop-domain" className="install-form-label">
                {t.install.domainLabel}
              </label>
              <div className="install-form-row">
                <input
                  id="shop-domain"
                  type="text"
                  name="shop"
                  autoComplete="off"
                  required
                  placeholder="my-store.myshopify.com"
                  value={shopInput}
                  onChange={(e) => {
                    setShopInput(e.target.value);
                    setError('');
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      startOAuth(e.currentTarget.form?.shop?.value || shopInput);
                    }
                  }}
                  className="install-form-input"
                />
                <button
                  type="submit"
                  className="install-form-submit"
                  disabled={submitting}
                >
                  {submitting ? c.submitting : c.submitLabel}
                </button>
              </div>
              {error && <p className="install-form-error">{error}</p>}
              <p className="install-form-hint">
                {c.hintExample} <code>my-store.myshopify.com</code>
                <br />
                {fill(c.hintAfter, vars)}
              </p>
            </form>
          </section>

          <section className="about-section">
            <h2>{c.opt2Title}</h2>
            <p>{fill(c.opt2Body, vars)}</p>
            <p style={{ marginTop: '1rem' }}>
              <a
                href={SHOPIFY_APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
                className="about-link"
                style={{
                  display: 'inline-block',
                  background: '#0f172a',
                  color: '#fff',
                  padding: '12px 20px',
                  borderRadius: '8px',
                  textDecoration: 'none',
                  fontWeight: 600,
                }}
              >
                {fill(c.opt2Cta, vars)}
              </a>
            </p>
          </section>

          <section className="about-section">
            <h2>{c.nextTitle}</h2>
            <ol>
              <li>{fill(c.next1, vars)}</li>
              <li>{c.next2}</li>
              <li>{fill(c.next3, vars)}</li>
            </ol>
            <p style={{ marginTop: '16px' }}>
              {c.compareLead} <Link to={localePath('/pricing/')} className="about-link">{c.comparePricing}</Link>
              {' '}{c.setupLead}{' '}
              <Link to={localePath('/help/')} className="about-link">{c.setupHelp}</Link>.
            </p>
          </section>
        </div>
      </div>
    </Layout>
  );
}